# ============================================================
# LOGISHIELD V2 ML PREDICTION GENERATOR
# ============================================================
#
# Purpose:
#   Replace the incorrect simulated shipment risk predictions
#   with predictions generated by the trained V2 ML pipeline.
#
# Model:
#   models/delay_prediction/shipment_delay_model_v2.joblib
#
# Database table updated:
#   shipment_risk_predictions
#
# IMPORTANT:
#   This script does NOT regenerate shipments, routes, vehicles,
#   disruptions, inventory, or any other project data.
#
# ============================================================

from __future__ import annotations

import os
import sys
import traceback
from pathlib import Path
from datetime import datetime
from getpass import getpass

import joblib
import numpy as np
import pandas as pd
import psycopg2
from psycopg2.extras import execute_batch


# ============================================================
# PATHS
# ============================================================

PROJECT_ROOT = Path(__file__).resolve().parents[1]

MODEL_PATH = (
    PROJECT_ROOT
    / "models"
    / "delay_prediction"
    / "shipment_delay_model_v2.joblib"
)


# ============================================================
# DATABASE CONFIGURATION
# ============================================================

DB_HOST = os.getenv("LOGISHIELD_DB_HOST", "localhost")
DB_PORT = int(os.getenv("LOGISHIELD_DB_PORT", "5432"))
DB_NAME = os.getenv("LOGISHIELD_DB_NAME", "logishield")
DB_USER = os.getenv("LOGISHIELD_DB_USER", "postgres")

DB_PASSWORD = os.getenv("LOGISHIELD_DB_PASSWORD")


# ============================================================
# CONFIGURATION
# ============================================================

MODEL_VERSION = "LogiShield-Delay-V2"

BATCH_SIZE = 5000


# ============================================================
# DISPLAY HELPERS
# ============================================================

def title(message: str) -> None:
    print()
    print("=" * 70)
    print(message)
    print("=" * 70)


def info(message: str) -> None:
    print(f"[INFO] {message}")


def success(message: str) -> None:
    print(f"[OK]   {message}")


def warning(message: str) -> None:
    print(f"[WARN] {message}")


def fail(message: str) -> None:
    print(f"[ERROR] {message}")


# ============================================================
# DATABASE
# ============================================================

def get_connection():
    global DB_PASSWORD

    if DB_PASSWORD is None:
        DB_PASSWORD = getpass(
            f"PostgreSQL password for {DB_USER}: "
        )

    info("Connecting to PostgreSQL...")

    connection = psycopg2.connect(
        host=DB_HOST,
        port=DB_PORT,
        dbname=DB_NAME,
        user=DB_USER,
        password=DB_PASSWORD,
    )

    connection.autocommit = False

    success("PostgreSQL connection established.")

    return connection


# ============================================================
# LOAD MODEL
# ============================================================

def load_model():

    title("LOADING LOGISHIELD V2 MODEL")

    if not MODEL_PATH.exists():
        raise FileNotFoundError(
            f"Model not found:\n{MODEL_PATH}"
        )

    info(f"Model path: {MODEL_PATH}")

    model = joblib.load(MODEL_PATH)

    success(
        f"Loaded: {type(model).__name__}"
    )

    if not hasattr(model, "predict_proba"):
        raise RuntimeError(
            "The saved V2 model does not support predict_proba()."
        )

    if hasattr(model, "classes_"):
        info(
            f"Model classes: {list(model.classes_)}"
        )

    return model


# ============================================================
# LOAD SHIPMENTS + RELATED DATA
# ============================================================

def load_training_like_data(connection):

    title("LOADING SHIPMENT INFERENCE DATA")

    query = """
        SELECT

            s.shipment_id,
            s.shipment_code,
            s.departure_time,
            s.expected_delivery_time,
            s.actual_delivery_time,

            s.source_location_id,
            s.destination_location_id,

            s.product_id,
            s.vehicle_id,

            s.quantity_units,
            s.weight_kg,

            s.weather_condition,
            s.weather_severity,

            s.traffic_level,
            s.traffic_severity,

            s.active_disruptions,
            s.max_disruption_severity,

            s.status,

            p.category AS product_category,
            p.unit_price,
            p.unit_weight_kg,

            src.city AS source_city,
            src.state AS source_state,
            src.latitude AS source_latitude,
            src.longitude AS source_longitude,

            dst.city AS destination_city,
            dst.state AS destination_state,
            dst.latitude AS destination_latitude,
            dst.longitude AS destination_longitude,

            v.vehicle_type,
            v.capacity_kg,
            v.fuel_efficiency_km_per_litre,

            r.distance_km,
            r.estimated_time_hours,
            r.base_cost,
            r.risk_score AS route_risk_score,
            r.route_status

        FROM shipments AS s

        INNER JOIN products AS p
            ON p.product_id = s.product_id

        INNER JOIN locations AS src
            ON src.location_id = s.source_location_id

        INNER JOIN locations AS dst
            ON dst.location_id = s.destination_location_id

        INNER JOIN vehicles AS v
            ON v.vehicle_id = s.vehicle_id

        INNER JOIN routes AS r
            ON r.source_location_id = s.source_location_id
           AND r.destination_location_id = s.destination_location_id

        ORDER BY s.shipment_id;
    """

    df = pd.read_sql_query(
        query,
        connection
    )

    info(
        f"Rows loaded: {len(df):,}"
    )

    if df.empty:
        raise RuntimeError(
            "No shipment rows were returned."
        )

    return df


# ============================================================
# EXACT V2 FEATURE ENGINEERING
# ============================================================

def create_v2_features(df: pd.DataFrame) -> pd.DataFrame:

    title("CREATING EXACT V2 FEATURES")

    df = df.copy()

    # --------------------------------------------------------
    # Timestamp
    # --------------------------------------------------------

    df["departure_time"] = pd.to_datetime(
        df["departure_time"],
        errors="coerce"
    )

    invalid = int(
        df["departure_time"].isna().sum()
    )

    if invalid:
        warning(
            f"Dropping {invalid} rows with invalid timestamps."
        )

        df = df.dropna(
            subset=["departure_time"]
        ).copy()

    # --------------------------------------------------------
    # Numeric columns
    # --------------------------------------------------------

    numeric_columns = [
        "quantity_units",
        "weight_kg",
        "unit_price",
        "unit_weight_kg",
        "capacity_kg",
        "fuel_efficiency_km_per_litre",
        "distance_km",
        "estimated_time_hours",
        "base_cost",
        "route_risk_score",
        "weather_severity",
        "traffic_severity",
        "active_disruptions",
        "max_disruption_severity",
        "source_latitude",
        "source_longitude",
        "destination_latitude",
        "destination_longitude",
    ]

    for column in numeric_columns:
        df[column] = pd.to_numeric(
            df[column],
            errors="coerce"
        )

    # --------------------------------------------------------
    # TIME FEATURES
    # --------------------------------------------------------

    df["departure_hour"] = (
        df["departure_time"].dt.hour
    )

    df["departure_day_of_week"] = (
        df["departure_time"].dt.dayofweek
    )

    df["departure_month"] = (
        df["departure_time"].dt.month
    )

    df["departure_week"] = (
        df["departure_time"]
        .dt.isocalendar()
        .week
        .astype(int)
    )

    df["is_weekend"] = (
        df["departure_day_of_week"] >= 5
    ).astype(int)

    df["is_peak_departure"] = (
        (
            df["departure_hour"].between(7, 10)
        )
        |
        (
            df["departure_hour"].between(17, 21)
        )
    ).astype(int)

    # --------------------------------------------------------
    # VEHICLE UTILIZATION
    # --------------------------------------------------------

    df["vehicle_utilization"] = (
        df["weight_kg"]
        /
        df["capacity_kg"].replace(0, np.nan)
    )

    df["vehicle_remaining_capacity"] = (
        df["capacity_kg"]
        -
        df["weight_kg"]
    )

    # --------------------------------------------------------
    # ROUTE FEATURES
    # --------------------------------------------------------

    df["distance_per_hour"] = (
        df["distance_km"]
        /
        df["estimated_time_hours"].replace(
            0,
            np.nan
        )
    )

    df["cost_per_km"] = (
        df["base_cost"]
        /
        df["distance_km"].replace(
            0,
            np.nan
        )
    )

    # --------------------------------------------------------
    # SHIPMENT VALUE
    # --------------------------------------------------------

    df["shipment_value"] = (
        df["quantity_units"]
        *
        df["unit_price"]
    )

    # --------------------------------------------------------
    # GEOGRAPHIC DELTA
    # --------------------------------------------------------

    latitude_difference = (
        df["destination_latitude"]
        -
        df["source_latitude"]
    )

    longitude_difference = (
        df["destination_longitude"]
        -
        df["source_longitude"]
    )

    df["geographic_delta"] = np.sqrt(
        latitude_difference ** 2
        +
        longitude_difference ** 2
    )

    # --------------------------------------------------------
    # MONSOON
    # --------------------------------------------------------

    df["is_monsoon"] = (
        df["departure_month"]
        .isin([6, 7, 8, 9])
    ).astype(int)

    # --------------------------------------------------------
    # FESTIVAL SEASON
    # --------------------------------------------------------

    df["is_festival_season"] = (
        df["departure_month"]
        .isin([10, 11])
    ).astype(int)

    # --------------------------------------------------------
    # DISRUPTION EXPOSURE
    # --------------------------------------------------------

    df["has_active_disruption"] = (
        df["active_disruptions"] > 0
    ).astype(int)

    df["has_severe_disruption"] = (
        df["max_disruption_severity"] >= 4
    ).astype(int)

    # --------------------------------------------------------
    # WEATHER RISK
    # --------------------------------------------------------

    df["has_bad_weather"] = (
        df["weather_severity"] >= 3
    ).astype(int)

    # --------------------------------------------------------
    # TRAFFIC RISK
    # --------------------------------------------------------

    df["has_heavy_traffic"] = (
        df["traffic_severity"] >= 2
    ).astype(int)

    # --------------------------------------------------------
    # CONDITION INTERACTIONS
    # --------------------------------------------------------

    df["weather_traffic_interaction"] = (
        df["weather_severity"]
        *
        df["traffic_severity"]
    )

    df["disruption_weather_interaction"] = (
        df["active_disruptions"]
        *
        df["weather_severity"]
    )

    df["disruption_traffic_interaction"] = (
        df["active_disruptions"]
        *
        df["traffic_severity"]
    )

    # --------------------------------------------------------
    # Fill values exactly enough for inference.
    # The saved sklearn pipeline will perform its own
    # preprocessing, but raw NaNs must not remain in the
    # columns selected by the pipeline.
    # --------------------------------------------------------

    numeric_engineered = [
        column
        for column in df.columns
        if column in {
            "quantity_units",
            "weight_kg",
            "unit_weight_kg",
            "unit_price",
            "capacity_kg",
            "fuel_efficiency_km_per_litre",
            "distance_km",
            "estimated_time_hours",
            "base_cost",
            "route_risk_score",
            "weather_severity",
            "traffic_severity",
            "active_disruptions",
            "max_disruption_severity",
            "departure_hour",
            "departure_day_of_week",
            "departure_month",
            "departure_week",
            "is_weekend",
            "is_peak_departure",
            "vehicle_utilization",
            "vehicle_remaining_capacity",
            "distance_per_hour",
            "cost_per_km",
            "shipment_value",
            "geographic_delta",
            "is_monsoon",
            "is_festival_season",
            "has_active_disruption",
            "has_severe_disruption",
            "has_bad_weather",
            "has_heavy_traffic",
            "weather_traffic_interaction",
            "disruption_weather_interaction",
            "disruption_traffic_interaction",
        }
    ]

    for column in numeric_engineered:
        df[column] = df[column].replace(
            [np.inf, -np.inf],
            np.nan
        )

    success(
        "V2 feature engineering completed."
    )

    return df


# ============================================================
# DISCOVER EXACT MODEL INPUT COLUMNS
# ============================================================

def get_model_input_columns(model):

    title("READING MODEL FEATURE SCHEMA")

    # The saved object is a sklearn Pipeline.
    #
    # Instead of hard-coding a possibly different list,
    # inspect the fitted preprocessing step and retrieve the
    # exact columns used during training.

    if not hasattr(model, "named_steps"):
        raise RuntimeError(
            "Expected the saved V2 model to be a sklearn Pipeline."
        )

    preprocessor = model.named_steps.get(
        "preprocessor"
    )

    if preprocessor is None:
        raise RuntimeError(
            "The saved V2 Pipeline does not contain "
            "a 'preprocessor' step."
        )

    numerical = []
    categorical = []

    for name, transformer, columns in (
        preprocessor.transformers_
    ):

        if name == "numeric":
            numerical = list(columns)

        elif name == "categorical":
            categorical = list(columns)

    if not numerical and not categorical:
        raise RuntimeError(
            "Could not discover numeric/categorical "
            "feature columns from the saved model."
        )

    info(
        f"Model numeric columns: {len(numerical)}"
    )

    info(
        f"Model categorical columns: {len(categorical)}"
    )

    print()

    print("Numeric features:")

    for column in numerical:
        print(f"  - {column}")

    print()

    print("Categorical features:")

    for column in categorical:
        print(f"  - {column}")

    return numerical, categorical


# ============================================================
# PREPARE MODEL INPUT
# ============================================================

def prepare_model_input(
    df,
    numerical_columns,
    categorical_columns
):

    all_columns = (
        numerical_columns
        +
        categorical_columns
    )

    missing = [
        column
        for column in all_columns
        if column not in df.columns
    ]

    if missing:
        raise RuntimeError(
            "The V2 feature engineering did not create "
            "all columns required by the trained model:\n"
            +
            "\n".join(
                f"  - {column}"
                for column in missing
            )
        )

    X = df[
        all_columns
    ].copy()

    # --------------------------------------------------------
    # Numeric cleanup
    # --------------------------------------------------------

    for column in numerical_columns:

        X[column] = pd.to_numeric(
            X[column],
            errors="coerce"
        )

        X[column] = (
            X[column]
            .replace(
                [np.inf, -np.inf],
                np.nan
            )
        )

        # The training pipeline used median imputation.
        # Filling here prevents inference-time failures if a
        # database value is unexpectedly missing.
        median = X[column].median()

        if pd.isna(median):
            median = 0.0

        X[column] = X[column].fillna(
            median
        )

    # --------------------------------------------------------
    # Categorical cleanup
    # --------------------------------------------------------

    for column in categorical_columns:

        X[column] = (
            X[column]
            .astype("string")
            .fillna("UNKNOWN")
        )

    return X


# ============================================================
# FIND DELAYED CLASS
# ============================================================

def get_delayed_class_index(model):

    if not hasattr(model, "classes_"):
        raise RuntimeError(
            "The saved model has no classes_ attribute."
        )

    classes = list(
        model.classes_
    )

    info(
        f"Model classes: {classes}"
    )

    # Most likely V2 target representation.
    for candidate in [
        "DELAYED",
        1,
        "1",
        True,
    ]:

        if candidate in classes:
            return classes.index(
                candidate
            )

    raise RuntimeError(
        "Could not identify the DELAYED class. "
        f"Available classes: {classes}"
    )


# ============================================================
# GENERATE PREDICTIONS
# ============================================================

def generate_predictions(
    model,
    df,
    numerical_columns,
    categorical_columns
):

    title("RUNNING V2 ML INFERENCE")

    X = prepare_model_input(
        df,
        numerical_columns,
        categorical_columns
    )

    info(
        f"Rows sent to model: {len(X):,}"
    )

    info(
        "Running predict_proba()..."
    )

    probabilities = model.predict_proba(X)

    delayed_index = get_delayed_class_index(
        model
    )

    delay_probability = (
        probabilities[:, delayed_index]
    )

    delay_probability = np.clip(
        delay_probability,
        0.0,
        1.0
    )

    df["delay_probability"] = (
        delay_probability
    )

    # --------------------------------------------------------
    # RISK SCORE
    # --------------------------------------------------------

    df["risk_score"] = (
        df["delay_probability"] * 100.0
    )

    # --------------------------------------------------------
    # RISK LEVEL
    # --------------------------------------------------------

    df["risk_level"] = np.select(
        [
            df["delay_probability"] >= 0.75,
            df["delay_probability"] >= 0.50,
            df["delay_probability"] >= 0.25,
        ],
        [
            "CRITICAL",
            "HIGH",
            "MEDIUM",
        ],
        default="LOW"
    )

    # --------------------------------------------------------
    # EXPECTED DELAY HOURS
    # --------------------------------------------------------
    #
    # Your current V2 model is a classification model, not a
    # regression model. Therefore this is an operational
    # estimate, not a separately learned regression output.
    #
    # Probability × route estimated time × 0.50
    #
    # We keep this transparent in prediction_reason.
    # --------------------------------------------------------

    df["predicted_delay_hours"] = (
        df["delay_probability"]
        *
        pd.to_numeric(
            df["estimated_time_hours"],
            errors="coerce"
        )
        *
        0.50
    )

    df["predicted_delay_hours"] = (
        df["predicted_delay_hours"]
        .replace(
            [np.inf, -np.inf],
            np.nan
        )
        .fillna(0)
        .clip(lower=0)
    )

    # --------------------------------------------------------
    # EXPLANATION
    # --------------------------------------------------------

    def build_reason(row):

        reasons = []

        if float(row["weather_severity"]) >= 3:
            reasons.append(
                "Severe weather"
            )

        if float(row["traffic_severity"]) >= 2:
            reasons.append(
                "Heavy traffic"
            )

        if int(row["active_disruptions"]) > 0:
            reasons.append(
                "Active disruption"
            )

        if float(row["max_disruption_severity"]) >= 4:
            reasons.append(
                "High-severity disruption"
            )

        if float(row["route_risk_score"]) >= 25:
            reasons.append(
                "Elevated route risk"
            )

        if (
            float(row["vehicle_utilization"])
            >= 0.80
        ):
            reasons.append(
                "High vehicle utilization"
            )

        if not reasons:
            reasons.append(
                "Prediction generated from "
                "LogiShield V2 ML features"
            )

        return "; ".join(reasons)

    df["prediction_reason"] = df.apply(
        build_reason,
        axis=1
    )

    success(
        "Individual shipment probabilities generated."
    )

    return df


# ============================================================
# DISPLAY DISTRIBUTION
# ============================================================

def display_distribution(df):

    title("V2 PREDICTION DISTRIBUTION")

    probabilities = (
        df["delay_probability"]
    )

    print(
        f"Total shipments      : {len(df):,}"
    )

    print(
        f"Minimum probability  : "
        f"{probabilities.min():.4f}"
    )

    print(
        f"Maximum probability  : "
        f"{probabilities.max():.4f}"
    )

    print(
        f"Average probability  : "
        f"{probabilities.mean():.4f}"
    )

    print(
        f"Unique probabilities : "
        f"{probabilities.nunique():,}"
    )

    print()
    print("Risk distribution:")

    counts = (
        df["risk_level"]
        .value_counts()
        .reindex(
            [
                "CRITICAL",
                "HIGH",
                "MEDIUM",
                "LOW"
            ],
            fill_value=0
        )
    )

    for level, count in counts.items():

        percentage = (
            count
            /
            len(df)
            *
            100
        )

        print(
            f"  {level:<10} "
            f"{count:>8,} "
            f"({percentage:>6.2f}%)"
        )


# ============================================================
# SAVE TO DATABASE
# ============================================================

def save_predictions(
    connection,
    df
):

    title("REPLACING SIMULATED PREDICTIONS")

    cursor = connection.cursor()

    try:

        # This table only contains derived prediction results.
        # It is safe to replace these rows without regenerating
        # the underlying logistics dataset.

        cursor.execute(
            """
            TRUNCATE TABLE
                shipment_risk_predictions
            RESTART IDENTITY;
            """
        )

        success(
            "Old simulated predictions removed."
        )

        insert_sql = """
            INSERT INTO shipment_risk_predictions
            (
                shipment_id,
                delay_probability,
                risk_score,
                risk_level,
                predicted_delay_hours,
                prediction_reason,
                model_version
            )
            VALUES
            (
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s
            );
        """

        records = []

        for row in df.itertuples(
            index=False
        ):

            records.append(
                (
                    int(row.shipment_id),

                    round(
                        float(
                            row.delay_probability
                        ),
                        4
                    ),

                    round(
                        float(
                            row.risk_score
                        ),
                        2
                    ),

                    str(
                        row.risk_level
                    ),

                    round(
                        float(
                            row.predicted_delay_hours
                        ),
                        2
                    ),

                    str(
                        row.prediction_reason
                    ),

                    MODEL_VERSION,
                )
            )

        info(
            f"Inserting {len(records):,} predictions..."
        )

        execute_batch(
            cursor,
            insert_sql,
            records,
            page_size=BATCH_SIZE
        )

        connection.commit()

        success(
            f"Inserted {len(records):,} V2 predictions."
        )

    except Exception:

        connection.rollback()

        raise

    finally:

        cursor.close()


# ============================================================
# VERIFY DATABASE
# ============================================================

def verify_database(
    connection
):

    title("VERIFYING NEW PREDICTIONS")

    cursor = connection.cursor()

    # --------------------------------------------------------
    # BASIC STATS
    # --------------------------------------------------------

    cursor.execute(
        """
        SELECT
            COUNT(*),
            MIN(delay_probability),
            MAX(delay_probability),
            AVG(delay_probability),
            COUNT(DISTINCT delay_probability)
        FROM shipment_risk_predictions;
        """
    )

    (
        total,
        minimum_probability,
        maximum_probability,
        average_probability,
        unique_probabilities,
    ) = cursor.fetchone()

    print(
        f"Total predictions     : {total:,}"
    )

    print(
        f"Minimum probability   : "
        f"{float(minimum_probability):.4f}"
    )

    print(
        f"Maximum probability   : "
        f"{float(maximum_probability):.4f}"
    )

    print(
        f"Average probability   : "
        f"{float(average_probability):.4f}"
    )

    print(
        f"Unique probabilities  : "
        f"{unique_probabilities:,}"
    )

    # --------------------------------------------------------
    # RISK LEVELS
    # --------------------------------------------------------

    print()
    print("Risk levels:")

    cursor.execute(
        """
        SELECT
            risk_level,
            COUNT(*)
        FROM shipment_risk_predictions
        GROUP BY risk_level
        ORDER BY COUNT(*) DESC;
        """
    )

    for level, count in cursor.fetchall():

        percentage = (
            count / total * 100
            if total
            else 0
        )

        print(
            f"  {level:<10}"
            f"{count:>8,}"
            f" ({percentage:>6.2f}%)"
        )

    # --------------------------------------------------------
    # MODEL VERSION
    # --------------------------------------------------------

    print()
    print("Model versions:")

    cursor.execute(
        """
        SELECT
            model_version,
            COUNT(*)
        FROM shipment_risk_predictions
        GROUP BY model_version
        ORDER BY model_version;
        """
    )

    for version, count in cursor.fetchall():

        print(
            f"  {version}: {count:,}"
        )

    # --------------------------------------------------------
    # SAMPLE
    # --------------------------------------------------------

    print()
    print("First 10 predictions:")

    cursor.execute(
        """
        SELECT
            shipment_id,
            delay_probability,
            risk_score,
            risk_level,
            predicted_delay_hours,
            model_version
        FROM shipment_risk_predictions
        ORDER BY shipment_id
        LIMIT 10;
        """
    )

    for row in cursor.fetchall():

        print(
            f"  Shipment {int(row[0]):>6} | "
            f"Probability {float(row[1]):.4f} | "
            f"Score {float(row[2]):>6.2f} | "
            f"{str(row[3]):<8} | "
            f"Delay {float(row[4]):>7.2f}h | "
            f"{row[5]}"
        )

    cursor.close()


# ============================================================
# MAIN
# ============================================================

def main():

    start = datetime.now()

    title(
        "LOGISHIELD V2 ML PREDICTION GENERATOR"
    )

    print(
        f"Project root : {PROJECT_ROOT}"
    )

    print(
        f"Model        : {MODEL_PATH}"
    )

    print(
        f"Database     : {DB_NAME}"
    )

    print(
        f"Model version: {MODEL_VERSION}"
    )

    connection = None

    try:

        # ----------------------------------------------------
        # 1. LOAD MODEL
        # ----------------------------------------------------

        model = load_model()

        # ----------------------------------------------------
        # 2. READ EXACT MODEL FEATURE SCHEMA
        # ----------------------------------------------------

        numerical_columns, categorical_columns = (
            get_model_input_columns(model)
        )

        # ----------------------------------------------------
        # 3. CONNECT DATABASE
        # ----------------------------------------------------

        connection = get_connection()

        # ----------------------------------------------------
        # 4. LOAD DATA
        # ----------------------------------------------------

        df = load_training_like_data(
            connection
        )

        # ----------------------------------------------------
        # 5. CREATE FEATURES
        # ----------------------------------------------------

        df = create_v2_features(
            df
        )

        # ----------------------------------------------------
        # 6. PREDICT
        # ----------------------------------------------------

        df = generate_predictions(
            model,
            df,
            numerical_columns,
            categorical_columns
        )

        # ----------------------------------------------------
        # 7. DISPLAY DISTRIBUTION
        # ----------------------------------------------------

        display_distribution(
            df
        )

        # ----------------------------------------------------
        # 8. SAVE
        # ----------------------------------------------------

        save_predictions(
            connection,
            df
        )

        # ----------------------------------------------------
        # 9. VERIFY
        # ----------------------------------------------------

        verify_database(
            connection
        )

        # ----------------------------------------------------
        # 10. COMPLETE
        # ----------------------------------------------------

        elapsed = (
            datetime.now() - start
        ).total_seconds()

        title(
            "LOGISHIELD V2 ML PREDICTIONS COMPLETE"
        )

        print(
            f"Runtime: {elapsed / 60:.2f} minutes"
        )

        print()
        print(
            "DATABASE STATUS: UPDATED"
        )

    except Exception as exc:

        if connection is not None:

            try:
                connection.rollback()
            except Exception:
                pass

        title(
            "LOGISHIELD V2 ML PREDICTION GENERATION FAILED"
        )

        fail(str(exc))

        print()
        traceback.print_exc()

        sys.exit(1)

    finally:

        if connection is not None:
            connection.close()

            info(
                "PostgreSQL connection closed."
            )


# ============================================================
# ENTRY POINT
# ============================================================

if __name__ == "__main__":
    main()